'EPIC-008'; from datetime import date; from decimal import Decimal; from uuid import UUID; from common.testing.ac_proof import ac_proof; from sqlalchemy.ext.asyncio import AsyncSession; from src.audit import JournalEntrySourceType; from src.identity import User; from src.ledger import Account, AccountType, post_journal_entry; from src.pricing import ManualValuationComponentType, ValuationService; from src.reporting import generate_balance_sheet; from tests.ledger._ledger_helpers import create_anchored_test_journal_entry as create_journal_entry
async def _account(db: AsyncSession, user_id: UUID, *, name: str, account_type: AccountType, currency: str='SGD') -> Account: account = Account(user_id=user_id, name=name, type=account_type, currency=currency); db.add(account); await db.flush(); await db.refresh(account); return account
async def _posted(db: AsyncSession, user_id: UUID, *, entry_date: date, memo: str, lines: list[dict[str, object]], source_type: JournalEntrySourceType) -> None: entry = await create_journal_entry(db=db, user_id=user_id, entry_date=entry_date, memo=memo, lines_data=lines, source_type=source_type); await post_journal_entry(db, entry.id, user_id)
@ac_proof('report-input-selection-excludes-superseded-pr', ac_ids=['AC-reporting.augmentation.1'], scope='behavioral', ci_tier='pr_ci', trust_mode='deterministic_pr', source_classes=['manual_record', 'bank_statement'], issue='#1103 / #990 / #992')
async def test_AC8_16_1_augmentation_seam_excludes_superseded_without_source_assurance(db: AsyncSession, test_user: User) -> None: 'AC-reporting.augmentation.1'; user_id = test_user.id; as_of = date(2026, 5, 31); service = ValuationService(); cash = await _account(db, user_id, name='Cash', account_type=AccountType.ASSET); equity = await _account(db, user_id, name='Opening Equity', account_type=AccountType.EQUITY); salary = await _account(db, user_id, name='Salary', account_type=AccountType.INCOME); await _posted(db, user_id, entry_date=date(2026, 5, 1), memo='Opening capital', lines=[{'account_id': cash.id, 'direction': 'DEBIT', 'amount': Decimal('1000.00'), 'currency': 'SGD'}, {'account_id': equity.id, 'direction': 'CREDIT', 'amount': Decimal('1000.00'), 'currency': 'SGD'}], source_type=JournalEntrySourceType.MANUAL); await _posted(db, user_id, entry_date=date(2026, 5, 10), memo='Auto-parsed deposit', lines=[{'account_id': cash.id, 'direction': 'DEBIT', 'amount': Decimal('500.00'), 'currency': 'SGD'}, {'account_id': salary.id, 'direction': 'CREDIT', 'amount': Decimal('500.00'), 'currency': 'SGD'}], source_type=JournalEntrySourceType.AUTO_PARSED); vkey = dict(component_type=ManualValuationComponentType.PROPERTY_VALUE, as_of_date=as_of, currency='SGD', source='manual appraisal'); await service.create_valuation_snapshot(db, user_id=user_id, value=Decimal('1000000.00'), **vkey); await service.create_valuation_snapshot(db, user_id=user_id, value=Decimal('1100000.00'), **vkey); await db.commit(); balance_sheet = await generate_balance_sheet(db, user_id, as_of_date=as_of, currency='SGD'); asset_lines = {line['name']: line for line in balance_sheet['assets']}; assert balance_sheet['total_assets'] == Decimal('1101500.00'); assert balance_sheet['equation_delta'] == Decimal('0.00'); assert balance_sheet['is_balanced'] is True; assert 'confidence_tier' not in asset_lines['Cash']; assert Decimal(str(asset_lines['Cash']['amount'])) == Decimal('1500.00'); components = await service.get_latest_valuation_components(db, user_id, as_of_date=as_of); assert components.total_assets == Decimal('1100000.00')
